                particle_j = self.particles[j]
                if np.allclose(particle_i.quantum_numbers, particle_j.quantum_numbers):
                    particle_j.change_quantum_number()

    def plot_probability_distribution(self):
        #here, we simulate a wavefront with a Gaussian distribution for simplicity
        x = np.linspace(-10., 10., num=1000)
        for idx, particle in enumerate(self.particles):
            y = np.exp(-0.5 * (x - particle.quantum_numbers[0])**2)
            plt.plot(x, y, label=f'Particle {idx+1}')
