import numpy as np
from typing import Tuple

# Function to evaluate the given numpy array
def max_min_diff(arr: np.ndarray) -> Tuple[int, int, int]:
    # Empty or Single element array cases
    if len(arr) < 2:
        return (0, 0, 0)
    diffs = []
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            diffs.append(abs(arr[i] - arr[j]))
    return (max(diffs), min(diffs), len(set(diffs)))

# Function to generate a two dimensional numpy array with random values
def random_array(n: int, val_range: Tuple[int, int]) -> np.ndarray:
    return np.random.randint(val_range[0], val_range[1], (n, n))
```
