```python
def train(iterations=50000):
    rl = QLearning(iterations=iterations)

    for i in range(iterations):
        game = TicTacToe()
        oldState = game.getState()

        while True:
            action = rl.chooseAction(oldState, game.actions)
            game.setAction(action)
            reward = game.gameEnded()

            if reward is not False:
                rl.updateQTableFromReward(oldState, action, reward, game.getState())
                break
            else:
                rl.updateQTableFromReward(oldState, action, reward, game.getState())
                oldState = game.getState()

        rl.updateExploration()
    return rl
